//! L2 Step 1 Part B — the gate parity oracle.
//!
//! Asserts that every ported admission gate in `order_management::gates` gives the SAME verdict as the
//! web's own gate for the same input, over all 96 cases in `docs/contracts/gate-vectors.json`.
//!
//! The expectations are not written here. That file is generated by
//! `scripts/contracts/gen-gate-vectors.ts`, which calls `lib/risk.ts` / `lib/hedging.ts` directly, so
//! a divergence breaks on one side or the other instead of hiding — the same direction as
//! `ask-markup-vectors.json` and `open-chain-vector.json`, with the web as the oracle.
//!
//! No database, and no feature gate: these are pure functions on both sides. `cargo test` runs it.
//!
//! The REASON STRING is compared too, not just pass/refuse. That is deliberate: the engine writes its
//! refusal into `"Order"."rejectionReason"`, which the trader reads, so a port that refuses correctly
//! with different words is still a visible divergence.

use order_management::gates;
use protocol::OrderSide;
use rust_decimal::Decimal;
use std::str::FromStr;

fn vectors() -> serde_json::Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../docs/contracts/gate-vectors.json");
    serde_json::from_str(&std::fs::read_to_string(path).expect("gate-vectors.json")).unwrap()
}

/// A decimal field that the generator writes as a string, or null.
fn dec_opt(v: &serde_json::Value) -> Option<Decimal> {
    v.as_str().map(|s| Decimal::from_str(s).expect("a decimal string"))
}

fn dec(v: &serde_json::Value) -> Decimal {
    dec_opt(v).expect("a required decimal")
}

fn text(v: &serde_json::Value) -> &str {
    v.as_str().expect("a required string")
}

fn side(v: &serde_json::Value) -> OrderSide {
    match text(v) {
        "BUY" => OrderSide::Buy,
        "SELL" => OrderSide::Sell,
        other => panic!("unknown side {other}"),
    }
}

fn ids(v: &serde_json::Value) -> Vec<String> {
    v.as_array().expect("an array").iter().map(|s| text(s).to_string()).collect()
}

/// Runs one case through the ported gate the vector names.
fn verdict(gate: &str, i: &serde_json::Value) -> Option<String> {
    match gate {
        "trading_halted" => gates::trading_halted(i["tradingHaltedAt"].as_bool().unwrap()),
        "close_only" => gates::close_only(i["closeOnlyAt"].as_bool().unwrap()),
        "group_trading_halted" => gates::group_trading_halted(i["tradingHaltedAt"].as_bool().unwrap()),
        "group_close_only" => gates::group_close_only(i["closeOnlyAt"].as_bool().unwrap()),
        "account_status_for_open" => gates::account_status_for_open(text(&i["status"])),
        "account_trading_rights_for_open" => gates::account_trading_rights_for_open(text(&i["status"]), text(&i["tradingRights"])),
        "symbol_trading_mode" => gates::symbol_trading_mode(text(&i["tradingMode"]), side(&i["side"])),
        "group_trading_restriction" => gates::group_trading_restriction(text(&i["restriction"]), side(&i["side"])),
        "group_max_lot" => gates::group_max_lot(dec(&i["volume"]), dec_opt(&i["groupMaxLot"])),
        "group_min_lot" => gates::group_min_lot(dec(&i["volume"]), dec_opt(&i["groupMinLot"]), dec(&i["symbolMinLot"])),
        "group_lot_step" => gates::group_lot_step(
            dec(&i["volume"]),
            dec_opt(&i["groupLotStep"]),
            dec_opt(&i["groupMinLot"]),
            dec(&i["symbolMinLot"]),
            dec(&i["symbolLotStep"]),
        ),
        "lot_step" => gates::lot_step(dec(&i["volume"]), dec(&i["minLot"]), dec(&i["lotStep"])),
        "group_allowed_symbol" => gates::group_allowed_symbol(
            i["restrictSymbols"].as_bool().unwrap(),
            &ids(&i["allowedSymbolIds"]),
            text(&i["symbolId"]),
        ),
        "max_open_positions" => gates::max_open_positions(
            i["openCount"].as_i64().unwrap(),
            i["maxOpenPositions"].as_i64().map(|v| v as i32),
        ),
        // `current` is null in the vector when the aggregate found no rows at all, which the web
        // coalesces to zero -- the port's caller must do the same, so the test does it here.
        "symbol_exposure" => gates::symbol_exposure(
            dec_opt(&i["current"]).unwrap_or(Decimal::ZERO),
            dec(&i["orderVolume"]),
            dec_opt(&i["maxExposure"]),
        ),
        "broker_exposure" => gates::broker_exposure(
            dec_opt(&i["current"]).unwrap_or(Decimal::ZERO),
            dec(&i["orderVolume"]),
            dec_opt(&i["totalExposureLimit"]),
        ),
        "max_daily_loss" => gates::max_daily_loss(
            dec_opt(&i["realizedToday"]).unwrap_or(Decimal::ZERO),
            dec_opt(&i["maxDailyLoss"]),
        ),
        "hedging_allowed" => gates::hedging_allowed(
            i["hedgingAllowed"].as_bool().unwrap(),
            i["hasOppositeOpenPosition"].as_bool().unwrap(),
        ),
        "price_freshness" => gates::price_freshness(i["tickAgeMs"].as_i64()),
        other => panic!("the vector names a gate this test does not dispatch: {other}"),
    }
}

#[test]
fn every_ported_gate_agrees_with_the_web_on_every_case() {
    let v = vectors();
    let gates_obj = v["gates"].as_object().expect("gates");
    // Pinned on purpose: if the generator grows a gate, this test must be re-read rather than quietly
    // covering less than it claims to.
    assert_eq!(gates_obj.len(), 19, "the contract file's gate list changed");

    let mut checked = 0;
    let mut rejects = 0;
    let mut mismatches: Vec<String> = Vec::new();
    for (gate, cases) in gates_obj {
        for (n, case) in cases.as_array().expect("cases").iter().enumerate() {
            let expected = case["reject"].as_str().map(str::to_string);
            let got = verdict(gate, &case["input"]);
            if got != expected {
                mismatches.push(format!(
                    "{gate}[{n}] input={} \n     web  = {expected:?}\n     rust = {got:?}",
                    case["input"]
                ));
            }
            if expected.is_some() {
                rejects += 1;
            }
            checked += 1;
        }
    }
    assert!(mismatches.is_empty(), "{} of {checked} cases disagree:\n{}", mismatches.len(), mismatches.join("\n"));
    assert_eq!(checked, 96, "the case count changed: re-read the vector");
    // and the file is not one-sided: a suite of only-passing cases would prove nothing
    assert!(rejects >= 30, "only {rejects} reject cases -- the vector must exercise both verdicts");
}

/// The invariant behind the numbers, asserted independently of the vector: a gate with its limit unset
/// must never refuse. Every one of these is `null = no limit` in the schema, and getting that backwards
/// would refuse every order on a broker that simply never configured the field.
#[test]
fn an_unset_limit_never_refuses() {
    assert!(gates::group_max_lot(Decimal::from(1000), None).is_none());
    assert!(gates::group_min_lot(Decimal::from_str("0.01").unwrap(), None, Decimal::from_str("0.01").unwrap()).is_none());
    assert!(gates::group_lot_step(Decimal::from_str("0.37").unwrap(), None, None, Decimal::from_str("0.01").unwrap(), Decimal::from_str("0.01").unwrap()).is_none());
    assert!(gates::max_open_positions(9_999, None).is_none());
    assert!(gates::symbol_exposure(Decimal::from(9_999), Decimal::from(1), None).is_none());
    assert!(gates::broker_exposure(Decimal::from(9_999), Decimal::from(1), None).is_none());
    assert!(gates::max_daily_loss(Decimal::from(-9_999), None).is_none());
    assert!(gates::group_allowed_symbol(false, &[], "anything").is_none());
    // and the two flags whose "off" is the default
    assert!(gates::trading_halted(false).is_none());
    assert!(gates::close_only(false).is_none());
    assert!(gates::group_trading_halted(false).is_none());
    assert!(gates::group_close_only(false).is_none());
    // hedging is the one whose permissive value is `true`, not `false` -- the web tests `!== false`
    assert!(gates::hedging_allowed(true, true).is_none());
}

/// And the opposite invariant: a gate that is configured and breached must refuse. Belt to the
/// vector's braces — if the generator ever produced an all-pass file, this still fails.
#[test]
fn a_breached_limit_always_refuses() {
    let d = |s: &str| Decimal::from_str(s).unwrap();
    assert!(gates::group_max_lot(d("1.01"), Some(d("1"))).is_some());
    assert!(gates::group_min_lot(d("0.05"), Some(d("0.10")), d("0.01")).is_some());
    assert!(gates::max_open_positions(5, Some(5)).is_some());
    assert!(gates::symbol_exposure(d("5"), d("0.01"), Some(d("5"))).is_some());
    assert!(gates::broker_exposure(d("100"), d("0.01"), Some(d("100"))).is_some());
    assert!(gates::max_daily_loss(d("-100"), Some(d("100"))).is_some());
    assert!(gates::group_allowed_symbol(true, &["other".to_string()], "s1").is_some());
    assert!(gates::trading_halted(true).is_some());
    assert!(gates::hedging_allowed(false, true).is_some());
    assert!(gates::account_status_for_open("SUSPENDED").is_some());
    assert!(gates::account_trading_rights_for_open("ACTIVE", "READ_ONLY").is_some());
    assert!(gates::symbol_trading_mode("BUY_ONLY", OrderSide::Sell).is_some());
    assert!(gates::group_trading_restriction("SELL_ONLY", OrderSide::Buy).is_some());
    assert!(gates::price_freshness(Some(10_000)).is_some());
    assert!(gates::price_freshness(None).is_some());
}
